// Normalize each RSS item for DB insertion
const sourceId = $('Split By Source').first().json.id;
const sourceAuthorityScore = $('Split By Source').first().json.authority_score || 20;

const items = [];

for (const item of $input.all()) {
  const raw = item.json;

  // URL canonicalization: strip UTM params, trailing slash, lowercase
  let url = (raw.link || raw.url || '').toString();
  url = url.replace(/[?&](utm_source|utm_medium|utm_campaign|utm_term|utm_content|ref|fbclid|gclid)=[^&]*/gi, '');
  url = url.replace(/[?&]+$/, '').replace('?&', '?').replace(/\/$/, '').toLowerCase();

  if (!url) continue;

  // SHA-256 URL hash (browser-compatible via TextEncoder)
  const msgBuffer = new TextEncoder().encode(url);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  const urlHash = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

  // Title normalization for trigram dedup (L2)
  const title = (raw.title || '').trim();
  const titleNormalized = title.toLowerCase().replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();

  // Excerpt: strip HTML, first 500 chars
  const excerpt = (raw.contentSnippet || raw.content || raw.summary || '')
    .replace(/<[^>]*>/g, '').trim().slice(0, 500);

  // Published date
  const publishedAt = raw.isoDate || raw.pubDate || new Date().toISOString();
  const hoursSince = (Date.now() - new Date(publishedAt).getTime()) / 3600000;

  // Freshness component (0-15, decays ~1.6pts/hour)
  const scoreFreshness = Math.max(0, 15 - Math.floor(hoursSince / 1.6));
  const prioritySkeleton = sourceAuthorityScore + scoreFreshness;

  if (!title) continue;

  items.push({
    source_id: sourceId,
    source_type: 'rss',
    source_url: url,
    url_hash: urlHash,
    title,
    title_normalized: titleNormalized,
    excerpt,
    author: raw.creator || raw.author || null,
    published_at: publishedAt,
    score_source_authority: sourceAuthorityScore,
    score_freshness: scoreFreshness,
    priority_score: Math.min(100, prioritySkeleton),
    pipeline_status: 'ingested'
  });
}

return items;
